"""Generate v37 provenance/reviewer-action artifacts without inventing approval or screening decisions."""
import collections
import csv
import hashlib
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]
D = ROOT / '10_FINAL_ADJUDICATION'
R = D / '06_REPORTS'
V = D / '05_REPRODUCTION/v37'
B = V / 'baseline'
