STAMP = 'Generated by `code/build_v37_followup.py`, 20 September 2026. Not human approval. Do not edit generated files by hand.'


def read(path):
    with open(ROOT / path, encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))


def save(path, rows):
    assert rows
    with open(path, 'w', newline='') as f:
        w = csv.DictWriter(f, list(dict.fromkeys(k for r in rows for k in r)))
        w.writeheader(); w.writerows(rows)


def doc(path, text):
    path.write_text(text.rstrip() + '\n')


results = {r['result_id']: r for r in read(D / '03_CANONICAL/results.csv')}
links = {r['result_id']: r for r in read('FINAL_RESULT_ROB2_LINKAGE.csv')}
spec = json.loads((D / '02_DECISIONS/model_specifications.json').read_text())
models = {m['model_id']: m for m in json.loads((D / '04_MODELS/model_outputs.json').read_text())}
grade = read(D / '03_CANONICAL/grade.csv')
members = collections.defaultdict(list)
for s in spec:
    if s['role'] != 'SENSITIVITY':
        for rid in s['result_ids']:
            members[rid].append(s['model_id'])

# Preserve exact historical candidates as versioned records; never silently replace selected assessments.
fields = {'study': 'study', 'outcome': 'outcome', 'timepoint': 'window',
          'intervention': 'intervention', 'comparator': 'comparator'}
domains = ['d1_randomisation', 'd2_deviations', 'd3_missing', 'd4_measurement', 'd5_reporting']
candidate_rows = []
candidate_by = collections.defaultdict(list)
scope = set(members) | {i for i, l in links.items() if l['rob2_assessment_id']}
for name in ['v34_rob2_draft_assessments.csv', 'v34_rob2_priority2_assessments.csv']:
    source = pathlib.Path('09_V34_ANALYSIS/03_ROB2') / name
    with open(ROOT / source, newline='') as f:
        reader = csv.DictReader(f); reader.fieldnames
        while True:
            line = reader.line_num + 1
            try: a = next(reader)
            except StopIteration: break
            for rid in sorted(scope):
                r = results[rid]
                if not all(a[x] == r[y] for x, y in fields.items()): continue
                if any(float(a[x]) != float(r[y]) for x, y in [('analysed_n_i', 'n_i'), ('analysed_n_c', 'n_c')]): continue
                if pathlib.Path(a['source_pdf']).name != pathlib.Path(r['source_pdf']).name: continue
                vec = [a[d] for d in domains] + [a['overall']]
                current = [links[rid]['d'+str(i)] for i in range(1, 6)] + [links[rid]['overall']]
                row = dict(result_id=rid, study=r['study'], assessment_version_key=f'{source}:L{line}',
                           source_sha256=hashlib.sha256((ROOT/source).read_bytes()).hexdigest(),
                           match_basis='Exact study/outcome/window/arms/analyzed Ns/PDF filename; arm statistics absent in this historical register',
                           **{'d'+str(i+1): a[d] for i,d in enumerate(domains)}, overall=a['overall'],
                           recorded_adopted_by=a['adopted_by'], recorded_adopted_date=a['adopted_date'],
                           provenance_note=a['provenance_note'], rationale=a['rationale'],
                           currently_linked=bool(links[rid]['rob2_assessment_id']),
                           same_as_selected_vector=vec == current,
                           status='CANDIDATE ONLY; reconcile version and source rationale; no approval transferred')
                candidate_rows.append(row); candidate_by[rid].append(row)

# One separately inspected corrected-register candidate: Zhu's day-before arm only.
rid = 'V33-OD-0020'
a = json.loads((ROOT/'ASTRA_VERIFICATION_SUPPORT/workbook.json').read_text())['Corrected_RoB2'][6]
assert a['Canonical study'] == 'Zhu 2022'
row = dict(result_id=rid, study='Zhu 2022', assessment_version_key='CORRECTED-V34-007@workbook.json:Corrected_RoB2:7',
           source_sha256=hashlib.sha256((ROOT/'ASTRA_VERIFICATION_SUPPORT/workbook.json').read_bytes()).hexdigest(),
           match_basis='Manually inspected day-before EA/usual-care vomiting 6–24h, 5/101 vs 22/101; not other active arms',
           **{'d'+str(i):a['Domain '+str(i)] for i in range(1,6)}, overall=a['Overall RoB 2'],
           recorded_adopted_by='', recorded_adopted_date='', provenance_note=a['Correction source'],
           rationale='Existing corrected-register candidate; reviewer reconciliation required', currently_linked=False,
           same_as_selected_vector=False, status='CANDIDATE ONLY; no approval transferred')
candidate_rows.append(row); candidate_by[rid].append(row)
save(Q/'rob2_existing_candidates.csv', candidate_rows)

work = []
for rid in sorted(members):
    r, l = results[rid], links[rid]
    work.append(dict(result_id=rid, study=r['study'], outcome=r['outcome'], window=r['window'],
        intervention=r['intervention'], comparator=r['comparator'], n_i=r['n_i'], n_c=r['n_c'],
        models=';'.join(members[rid]), source_pdf=r['source_pdf'], source_location=r['source_location'],
        current_assessment=l['rob2_assessment_id'], current_overall=l['overall'],
        candidate_versions=';'.join(a['assessment_version_key'] for a in candidate_by[rid]),
        action='RECONCILE SELECTED VERSION / SIGNOFF' if l['rob2_assessment_id'] else ('REVIEW EXISTING CANDIDATE' if candidate_by[rid] else 'RESULT-SPECIFIC ASSESSMENT NEEDED'),
        reviewer='', review_date='', final_decision='', evidence_locator=''))
save(Q/'rob2_non_sensitivity_worklist.csv', work)
save(Q/'grade_review_ledger.csv', [dict(**g, review_priority=('EXPLICIT REVIEW: v36 bowel-sounds downgrade' if g['model_id']=='bowelsounds_TEAS_sham' else 'EXPLICIT REVIEW: conflicting nausea RoB versions and serious vs very-serious downgrade' if g['model_id']=='nausea48_TEAS_sham' else 'Reviewer approval/revision required'), reviewer='', date='', decision='', rationale='') for g in grade])

